from pathlib import Path
import json
from decimal import Decimal
from datetime import datetime
from zoneinfo import ZoneInfo
ROOT=Path(__file__).resolve().parents[2]
rows=json.loads((ROOT/'analysis/jace-prices/cheapest.json').read_text());cards={r['name']:r for r in rows}
order=['Infernal Grasp','Anguished Unmaking','Wrath of God','Austere Command','Aetherize','Massacre Wurm','Oath of Gideon','Spectral Procession',"Sram's Expertise",'Clever Concealment',"Chandra's Ignition",'Fateful Absence','Toxic Deluge','Cyclonic Rift']
reasons={'Infernal Grasp':'Cheap creature removal; Forge uses it.', 'Anguished Unmaking':'Exiles a nonland permanent, including indestructible threats.', 'Wrath of God':'Reliable creature reset; Forge uses it.', 'Austere Command':'Flexible reset; can choose modes around your board.', 'Aetherize':'Defends against an attacking army; AI timing understates human use.', 'Massacre Wurm':'Your requested keeper; punishes small-creature boards.', 'Oath of Gideon':'Two blocking/fodder tokens and extra loyalty for entering planeswalkers.', 'Spectral Procession':'Three flying blockers/fodder; white mana requirement matters.', "Sram's Expertise":'Three blockers/fodder plus a free spell of mana value 3 or less.', 'Clever Concealment':'Protects your nonland board; useful alongside wipes.', "Chandra's Ignition":'Conditional wipe/payoff; needs your creature to survive until resolution.', 'Fateful Absence':'Flexible creature/planeswalker removal; optional if v0.7 wins out.', 'Toxic Deluge':'Efficient real-life wipe, but Forge is not casting it; optional if v0.7 wins out.', 'Cyclonic Rift':'Expensive upgrade; postpone until the comprehensive comparison is reviewed.'}
D=lambda x:Decimal(str(x))
total=sum(D(r['usd']) for r in rows);rift=D(cards['Cyclonic Rift']['usd']);nf=sum(D(r['nonfoil']['usd']) for r in rows)
L=['# Jace buy list — v0.6 candidate','',f'Prices checked {datetime.now(ZoneInfo("America/Los_Angeles")).strftime("%Y-%m-%d %H:%M %Z")}. **14 cards to buy: ${total:.2f} before shipping and tax. Budget candidate: ${total-rift:.2f}**, keeping your existing Theorix Charm instead of buying Cyclonic Rift.','', 'This is a shopping reference for the proposed list, not confirmation that the list is better or that anything has been purchased. Wait for the comprehensive run and timeout review before placing the full order. Your actual owned deck remains v0.1-real.','', '## Prioritized purchases','', 'One copy of each card. Priority reflects affordability, your removal-first plan and keeper choices, not a statistically proven ranking of individual cards. The first six cost $7.87. These are purchasing priorities; use the complete tested swap plan when assembling a candidate.','', '| Priority | Card | Cheapest eligible printing | Finish | USD | Purpose |','|---|---|---|---|---|---|']
for i,name in enumerate(order,1):
 r=cards[name];L.append(f"| {i} | [{name}]({r['url']}) | {r['set_name']} ({r['set'].upper()}) #{r['collector_number']} | {r['finish']} | ${r['usd']:.2f} | {reasons[name]} |")
L+=['', f'**Total: ${total:.2f}.** The cheapest Massacre Wurm is foil (Foundations #714, $1.95). If you prefer nonfoil, [Foundations #754]({cards["Massacre Wurm"]["nonfoil"]["url"]}) is $2.68; the all-nonfoil total is **${nf:.2f}**, or **${nf-rift:.2f} without Rift**. All other selected copies are nonfoil.','', '## Already owned — do not buy again','', '- Skrelv’s Hive — replaces Talisman of Indulgence. Mites can feed Jace but **cannot block**.', '- Dreadhorde Invasion — replaces Talisman of Creativity. Army can block, but only one Army grows; it does not make an additional independent token every upkeep.', '- Darksteel Angel — replaces Staff of Compleation. High-cost Jace payoff.', '- Keep Dreamtide Whale, Triplicate Titan and Loyal Tutor from your current deck. Massacre Wurm is a requested keeper in the candidate but still needs buying.', '- Mass Polymorph is owned but is not in v0.6. Oath of Teferi and Spark Double are not in v0.6 and are not on this shopping list.','', '## Exact swaps from your physical deck','', '| Remove from v0.1-real | Add in v0.6 | Purchase? |','|---|---|---|']
swaps=[("White Sun's Twilight","Chandra's Ignition"),('Theorix Charm','Cyclonic Rift'),('Despark','Oath of Gideon'),('Staff of Compleation','Darksteel Angel'),('Azorius Signet','Massacre Wurm'),('Flawless Maneuver','Clever Concealment'),('Fellwar Stone','Aetherize'),('Staff of the Storyteller','Wrath of God'),('Sunfall','Infernal Grasp'),('Proteus Staff','Fateful Absence'),('Cursed Mirror','Anguished Unmaking'),('Martial Coup','Austere Command'),('Synthetic Destiny','Toxic Deluge'),('Talisman of Indulgence',"Skrelv's Hive"),('Rakdos Signet','Spectral Procession'),('Izzet Signet',"Sram's Expertise"),('Talisman of Creativity','Dreadhorde Invasion')]
for out,add in swaps:L.append(f"| {out} | {add} | {'yes' if add in cards else 'owned spare'} |")
L+=['', '## Budget candidate — keep Theorix Charm','', f'Use the complete v0.6 list with exactly one change: **Cyclonic Rift → your owned Theorix Charm**. Buy the other 13 cards above for **${total-rift:.2f}**, use the three owned spares, and make 16 swaps from your physical deck. Saves **${rift:.2f}**.','', 'Deck file: [v0.6-codex-budget](gauntlet/versions/jace/v0.6-codex-budget/deck.dck). This budget list has not been simulated; it does not inherit v0.6’s 5/10 result, and Theorix Charm is not an equivalent replacement for an overloaded Rift. No existing candidate, run folder or shared engine file was changed.','', 'If the v0.7 anti-Ghalta experiment is selected later, do not buy Fateful Absence or Toxic Deluge for that list: it restores your owned Despark and adds Reality Shift instead. That is a separate experiment, not silently included in this v0.6 shopping total.','', '## Price method and evidence','', 'Started with the exact deck-file difference: 17 additions minus the three confirmed owned spares = 14 purchases. Used scryfall-sdk with `setAgent(\'mtg-commander\', \'1.0.0\')` and one batch `Cards.collection(...)` lookup. Node DNS failed in this environment, so the same collection was retrieved via curl with the same agent, followed by sequential Oracle-ID printing searches (no bursts).','', 'Compared all returned English paper printings and available USD nonfoil, foil and etched prices. Required Commander legality and excluded gold/silver borders and digital cards. This excludes the cheaper World Championship Wrath of God. Non-English prices, unpriced copies and individual shop inventory were not compared. Each selected printing is linked in the table. Prices are Scryfall reference values, not a live seller quote; shipping can exceed the savings from buying tiny singles at different stores.','', 'Raw collection and printing snapshots: `analysis/jace-prices/`. Cheapest selections: `analysis/jace-prices/cheapest.json`; reproducible selector: `printings.py`; document generator: `build-list.py`. A missing price is never treated as zero.','', 'Evidence supporting caution: [finished-run analysis](gauntlet/versions/jace/ANALYSIS.md). Toxic Deluge’s zero casts and the timeout-credit issue prevent treating the current simulation headline as a clean purchase justification.']
assert sum(D(cards[n]['usd']) for n in order[:6])==Decimal('7.87')
(ROOT/'JACE-BUY-LIST.md').write_text('\n'.join(L)+'\n')
print('Wrote buy list; total',total,'budget',total-rift)
